import { useState, useEffect, useCallback, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Sparkles, ChevronRight, Ticket, Zap, Crown } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { hapticLight } from '@/utils/haptics'

interface Slide {
  id: number
  theme: string
  badge?: string
  title: string
  titleAccent?: string
  highlight?: string
  subtitle: string
  action: string
  route: string
  // Visual
  bgFrom: string
  bgTo: string
  accentColor: string
  glowColor: string
  Icon: React.ElementType
  chipText: string
  chipColor: string
}

const slides: Slide[] = [
  {
    id: 1,
    theme: 'lottery',
    badge: 'EXCLUSIVE',
    title: 'ลุ้นกินฟรี',
    titleAccent: 'ทุกงวด!',
    subtitle: 'สั่งออเดอร์ = ได้ตั๋วลุ้น\nตรงหวยรัฐบาล ไม่ต้องซื้อ',
    action: 'ดูตั๋วของฉัน',
    route: '/lottery',
    bgFrom: '#064E3B',
    bgTo: '#0D1B2A',
    accentColor: '#34D399',
    glowColor: 'rgba(52,211,153,0.35)',
    Icon: Ticket,
    chipText: '1 ออเดอร์ = 1 ตั๋ว',
    chipColor: '#34D399',
  },
  {
    id: 2,
    theme: 'new',
    badge: 'NEW ARRIVAL',
    title: 'กะเพราหมูกรอบ',
    subtitle: 'หมูกรอบชิ้นใหญ่ ผัดแห้งๆ\nกรอบนอกนุ่มใน เริ่มต้น 65.-',
    action: 'สั่งเลย',
    route: '/',
    bgFrom: '#7C1D1D',
    bgTo: '#1A0A02',
    accentColor: '#FB923C',
    glowColor: 'rgba(251,146,60,0.35)',
    Icon: Zap,
    chipText: 'เปิดให้สั่งทุกวัน',
    chipColor: '#FB923C',
  },
  {
    id: 3,
    theme: 'vip',
    badge: 'MEMBERS ONLY',
    title: 'VIP สิทธิพิเศษ',
    highlight: '+ ส่วนลด 15%',
    subtitle: 'สะสมพอยต์ทุกออเดอร์\nแลกส่วนลดได้เลย',
    action: 'ดูสิทธิพิเศษ',
    route: '/profile',
    bgFrom: '#78350F',
    bgTo: '#1C1200',
    accentColor: '#FBBF24',
    glowColor: 'rgba(251,191,36,0.35)',
    Icon: Crown,
    chipText: 'สะสมแต้มทุกบาท',
    chipColor: '#FBBF24',
  },
]

export function HeroSlider() {
  const navigate = useNavigate()
  const [current, setCurrent] = useState(0)
  const [isAutoPlaying, setIsAutoPlaying] = useState(true)
  const [progress, setProgress] = useState(0)
  const timerRef = useRef<NodeJS.Timeout | null>(null)
  const dragStartX = useRef(0)
  const isDragging = useRef(false)

  const DURATION = 5500
  const STEP = 100 / (DURATION / 60)

  const goTo = useCallback((index: number) => {
    setCurrent(index)
    setProgress(0)
    setIsAutoPlaying(false)
    setTimeout(() => setIsAutoPlaying(true), 10000)
    hapticLight()
  }, [])

  const next = useCallback(() => {
    setCurrent(p => (p + 1) % slides.length)
    setProgress(0)
  }, [])

  const prev = useCallback(() => {
    setCurrent(p => (p - 1 + slides.length) % slides.length)
    setProgress(0)
  }, [])

  useEffect(() => {
    if (!isAutoPlaying) return
    timerRef.current = setInterval(() => {
      setProgress(p => {
        if (p >= 100) { next(); return 0 }
        return p + STEP
      })
    }, 60)
    return () => { if (timerRef.current) clearInterval(timerRef.current) }
  }, [isAutoPlaying, next, current])

  const slide = slides[current]

  const handlePointerDown = (e: React.PointerEvent) => {
    dragStartX.current = e.clientX
    isDragging.current = true
    setIsAutoPlaying(false)
  }

  const handlePointerUp = (e: React.PointerEvent) => {
    if (!isDragging.current) return
    const diff = dragStartX.current - e.clientX
    if (Math.abs(diff) > 48) diff > 0 ? next() : prev()
    isDragging.current = false
    setTimeout(() => setIsAutoPlaying(true), 6000)
  }

  return (
    <div
      className="relative overflow-hidden select-none touch-pan-y"
      style={{ borderRadius: 28 }}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
    >
      {/* Aspect ratio container */}
      <div style={{ paddingBottom: '52%', position: 'relative' }}>

        <AnimatePresence mode="wait">
          <motion.div
            key={slide.id}
            initial={{ opacity: 0, scale: 1.04 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.97 }}
            transition={{ duration: 0.5, ease: [0.4, 0, 0.2, 1] }}
            className="absolute inset-0"
            style={{
              background: `linear-gradient(145deg, ${slide.bgFrom} 0%, ${slide.bgTo} 100%)`,
            }}
          >
            {/* Ambient glow blob */}
            <motion.div
              animate={{ scale: [1, 1.15, 1], opacity: [0.6, 0.9, 0.6] }}
              transition={{ duration: 6, repeat: Infinity, ease: 'easeInOut' }}
              className="absolute -right-12 -top-12 w-64 h-64 rounded-full pointer-events-none"
              style={{
                background: `radial-gradient(circle, ${slide.glowColor} 0%, transparent 70%)`,
                filter: 'blur(32px)',
              }}
            />
            <motion.div
              animate={{ scale: [1, 1.2, 1] }}
              transition={{ duration: 8, repeat: Infinity, ease: 'easeInOut', delay: 2 }}
              className="absolute -left-8 bottom-0 w-40 h-40 rounded-full pointer-events-none"
              style={{
                background: `radial-gradient(circle, ${slide.glowColor} 0%, transparent 70%)`,
                filter: 'blur(24px)',
                opacity: 0.4,
              }}
            />

            {/* Large decorative icon */}
            <motion.div
              animate={{ rotate: [0, 6, -6, 0], y: [0, -6, 0] }}
              transition={{ duration: 7, repeat: Infinity, ease: 'easeInOut' }}
              className="absolute right-4 bottom-2 pointer-events-none"
              style={{ opacity: 0.12 }}
            >
              <slide.Icon
                className="w-32 h-32"
                style={{ color: slide.accentColor }}
              />
            </motion.div>

            {/* Content */}
            <div className="absolute inset-0 flex flex-col justify-center px-5 pb-7 pt-4">
              {/* Badge */}
              {slide.badge && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.1 }}
                  className="mb-2.5"
                >
                  <span
                    className="inline-flex items-center gap-1.5 text-[9px] font-black px-2.5 py-1 rounded-full tracking-[0.12em] uppercase"
                    style={{
                      background: `rgba(${hexToRgb(slide.accentColor)}, 0.18)`,
                      color: slide.accentColor,
                      border: `1px solid rgba(${hexToRgb(slide.accentColor)}, 0.35)`,
                    }}
                  >
                    <Sparkles className="w-2.5 h-2.5" />
                    {slide.badge}
                  </span>
                </motion.div>
              )}

              {/* Title */}
              <motion.h2
                initial={{ opacity: 0, y: 14 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.17 }}
                className="text-[1.65rem] font-black text-white leading-tight tracking-tight"
                style={{ textShadow: '0 2px 16px rgba(0,0,0,0.4)' }}
              >
                {slide.title}
                {slide.titleAccent && (
                  <span
                    className="block"
                    style={{
                      color: slide.accentColor,
                      textShadow: `0 0 28px ${slide.glowColor}`,
                    }}
                  >
                    {slide.titleAccent}
                  </span>
                )}
                {slide.highlight && (
                  <span
                    className="inline-flex items-center gap-1.5 text-lg px-3 py-0.5 rounded-xl ml-2 align-middle"
                    style={{
                      background: `rgba(${hexToRgb(slide.accentColor)}, 0.20)`,
                      color: slide.accentColor,
                      border: `1px solid rgba(${hexToRgb(slide.accentColor)}, 0.30)`,
                      fontSize: '0.85rem',
                    }}
                  >
                    {slide.highlight}
                  </span>
                )}
              </motion.h2>

              {/* Subtitle */}
              <motion.p
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.25 }}
                className="text-white/65 text-[12px] mt-2 mb-3.5 leading-relaxed"
              >
                {slide.subtitle.split('\n').map((line, i) => (
                  <span key={i} className="block">{line}</span>
                ))}
              </motion.p>

              {/* Bottom row: chip + CTA */}
              <motion.div
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.33 }}
                className="flex items-center gap-2.5"
              >
                {/* Info chip */}
                <span
                  className="text-[10px] font-black px-2.5 py-1.5 rounded-full"
                  style={{
                    background: 'rgba(255,255,255,0.09)',
                    color: 'rgba(255,255,255,0.75)',
                    border: '1px solid rgba(255,255,255,0.12)',
                  }}
                >
                  {slide.chipText}
                </span>

                {/* CTA */}
                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.92 }}
                  onClick={() => {
                    hapticLight()
                    navigate(slide.route)
                  }}
                  className="inline-flex items-center gap-1.5 text-[12px] font-black px-4 py-2 rounded-full cursor-pointer"
                  style={{
                    background: slide.accentColor,
                    color: '#000',
                    boxShadow: `0 6px 20px ${slide.glowColor}`,
                  }}
                >
                  {slide.action}
                  <ChevronRight className="w-3.5 h-3.5" />
                </motion.button>
              </motion.div>
            </div>
          </motion.div>
        </AnimatePresence>

        {/* Bottom gradient fade for dot contrast */}
        <div
          className="absolute bottom-0 inset-x-0 h-10 pointer-events-none"
          style={{ background: 'linear-gradient(to top, rgba(0,0,0,0.3), transparent)' }}
        />

        {/* Progress dots */}
        <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex items-center gap-1.5 z-20">
          {slides.map((_, i) => (
            <button
              key={i}
              type="button"
              onClick={() => goTo(i)}
              aria-label={`ไปสไลด์ที่ ${i + 1}`}
              className="relative overflow-hidden rounded-full transition-all duration-400 cursor-pointer"
              style={{
                width: i === current ? 24 : 6,
                height: 6,
                background: i === current ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.35)',
              }}
            >
              {i === current && (
                <motion.div
                  className="absolute inset-y-0 left-0 rounded-full"
                  style={{
                    width: `${progress}%`,
                    background: 'rgba(255,255,255,0.4)',
                  }}
                />
              )}
            </button>
          ))}
        </div>

        {/* Slide counter */}
        <div
          className="absolute top-3 right-3 z-20 text-[10px] font-black px-2 py-0.5 rounded-full"
          style={{
            background: 'rgba(0,0,0,0.35)',
            color: 'rgba(255,255,255,0.7)',
            backdropFilter: 'blur(8px)',
          }}
        >
          {current + 1} / {slides.length}
        </div>
      </div>
    </div>
  )
}

/** Convert hex color to "r,g,b" string for rgba() */
function hexToRgb(hex: string): string {
  const r = parseInt(hex.slice(1, 3), 16)
  const g = parseInt(hex.slice(3, 5), 16)
  const b = parseInt(hex.slice(5, 7), 16)
  return `${r},${g},${b}`
}
