import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { ClipboardList, Star, Clock, ChevronRight } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { useAuthStore } from '@/store'
import { useOrders } from '@/features/orders/hooks/useOrders'
import { fadeInUp } from '@/animations/variants'
import { useCountUp } from '@/hooks/useAdvancedAnimations'

// Simulated live delivery time (20-35 min range)
function useDeliveryTime() {
  const [minutes, setMinutes] = useState(() => Math.floor(Math.random() * 15) + 20)
  useEffect(() => {
    const id = setInterval(() => {
      setMinutes(Math.floor(Math.random() * 15) + 20)
    }, 45000)
    return () => clearInterval(id)
  }, [])
  return minutes
}

export function StatsRow() {
  const navigate = useNavigate()
  const { user } = useAuthStore()
  const { data: orders } = useOrders(user?.id)
  const deliveryTime = useDeliveryTime()

  const activeOrders = orders?.filter(
    o => ['placed', 'confirmed', 'preparing', 'ready'].includes(o.status)
  ).length || 0

  const points = user?.points || 0
  const hasActiveOrder = activeOrders > 0
  const countUpRef = useCountUp(points, 2.5)

  return (
    <motion.div variants={fadeInUp} className="grid grid-cols-3 gap-2.5">

      {/* === Active Orders === */}
      <motion.button
        onClick={() => navigate('/orders')}
        whileHover={{ y: -3, scale: 1.02 }}
        whileTap={{ scale: 0.96 }}
        className="relative overflow-hidden rounded-[20px] p-3.5 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-400 col-span-1"
        style={hasActiveOrder ? {
          background: 'linear-gradient(145deg, #1E40AF 0%, #1E3A8A 60%, #1E3374 100%)',
          boxShadow: '0 8px 24px rgba(30,64,175,0.5), inset 0 1px 0 rgba(255,255,255,0.1)',
          border: '1px solid rgba(59,130,246,0.3)',
        } : {
          background: 'var(--bg-card)',
          border: '1px solid var(--border-subtle)',
          boxShadow: 'var(--shadow-card)',
        }}
      >
        {hasActiveOrder && (
          <>
            <div className="absolute -right-4 -top-4 w-20 h-20 rounded-full blur-xl opacity-30" style={{ background: '#60A5FA' }} />
            <div className="absolute -left-3 -bottom-4 w-14 h-14 rounded-full blur-xl opacity-20" style={{ background: '#38BDF8' }} />
          </>
        )}

        <div className="relative">
          <div
            className="w-9 h-9 rounded-[12px] flex items-center justify-center mb-2"
            style={hasActiveOrder ? {
              background: 'rgba(255,255,255,0.12)',
              border: '1px solid rgba(255,255,255,0.2)'
            } : {
              background: 'rgba(59,130,246,0.10)',
              border: '1px solid rgba(59,130,246,0.15)'
            }}
          >
            <ClipboardList className="w-4.5 h-4.5" style={{ color: hasActiveOrder ? 'white' : '#60A5FA' }} />
          </div>

          <p className="text-[9px] font-bold mb-0.5" style={{ color: hasActiveOrder ? 'rgba(255,255,255,0.55)' : 'var(--text-muted)' }}>
            ออเดอร์
          </p>
          <div className="flex items-center gap-1">
            {hasActiveOrder && (
              <motion.span
                animate={{ scale: [1, 1.5, 1], opacity: [0.8, 0.3, 0.8] }}
                transition={{ duration: 1.4, repeat: Infinity }}
                className="w-1.5 h-1.5 rounded-full flex-shrink-0"
                style={{ background: '#93C5FD' }}
              />
            )}
            <p className="font-black text-[13px] num-display" style={{ color: hasActiveOrder ? 'white' : 'var(--text-primary)' }}>
              {hasActiveOrder ? `${activeOrders}` : '—'}
            </p>
          </div>
          {hasActiveOrder && (
            <p className="text-[9px] font-bold mt-0.5" style={{ color: 'rgba(255,255,255,0.45)' }}>กำลังทำ</p>
          )}
        </div>
      </motion.button>

      {/* === Delivery Time === */}
      <motion.div
        whileHover={{ y: -3, scale: 1.02 }}
        className="relative overflow-hidden rounded-[20px] p-3.5 col-span-1"
        style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border-subtle)',
          boxShadow: 'var(--shadow-card)',
        }}
      >
        <div className="relative">
          <div
            className="w-9 h-9 rounded-[12px] flex items-center justify-center mb-2"
            style={{
              background: 'rgba(16,185,129,0.10)',
              border: '1px solid rgba(16,185,129,0.15)',
            }}
          >
            <Clock className="w-4.5 h-4.5 text-emerald-400" />
          </div>

          <p className="text-[9px] font-bold mb-0.5" style={{ color: 'var(--text-muted)' }}>รอรับ</p>
          <div className="flex items-end gap-0.5">
            <motion.span
              key={deliveryTime}
              initial={{ opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              className="font-black text-[15px] num-display"
              style={{ color: 'var(--text-primary)' }}
            >
              {deliveryTime}
            </motion.span>
            <span className="text-[9px] font-bold mb-0.5" style={{ color: 'var(--text-muted)' }}>นาที</span>
          </div>
          <div className="flex items-center gap-1 mt-0.5">
            <div className="w-1 h-1 rounded-full bg-emerald-400" />
            <p className="text-[8px] font-bold text-emerald-400">อยู่ในเขตส่ง</p>
          </div>
        </div>
      </motion.div>

      {/* === Points === */}
      <motion.button
        onClick={() => navigate('/profile')}
        whileHover={{ y: -3, scale: 1.02 }}
        whileTap={{ scale: 0.96 }}
        className="relative overflow-hidden rounded-[20px] p-3.5 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-400 col-span-1"
        style={points > 0 ? {
          background: 'linear-gradient(145deg, #B45309 0%, #92400E 55%, #78350F 100%)',
          boxShadow: '0 8px 24px rgba(180,83,9,0.5), inset 0 1px 0 rgba(255,255,255,0.1)',
          border: '1px solid rgba(245,158,11,0.3)',
        } : {
          background: 'var(--bg-card)',
          border: '1px solid var(--border-subtle)',
          boxShadow: 'var(--shadow-card)',
        }}
      >
        {points > 0 && (
          <>
            <motion.div
              animate={{ x: ['-100%', '200%'] }}
              transition={{ duration: 3, repeat: Infinity, repeatDelay: 5 }}
              className="absolute inset-0 -skew-x-12 pointer-events-none"
              style={{ background: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.10), transparent)' }}
            />
            <div className="absolute -right-4 -top-4 w-20 h-20 rounded-full blur-xl opacity-25" style={{ background: '#FCD34D' }} />
          </>
        )}

        <div className="relative">
          <div
            className="w-9 h-9 rounded-[12px] flex items-center justify-center mb-2"
            style={points > 0 ? {
              background: 'rgba(255,255,255,0.12)',
              border: '1px solid rgba(255,255,255,0.2)'
            } : {
              background: 'rgba(245,158,11,0.10)',
              border: '1px solid rgba(245,158,11,0.15)'
            }}
          >
            <Star
              className="w-4.5 h-4.5"
              style={{
                color: points > 0 ? 'white' : '#FBBF24',
                fill: points > 0 ? 'rgba(255,255,255,0.4)' : 'none'
              }}
            />
          </div>

          <p className="text-[9px] font-bold mb-0.5" style={{ color: points > 0 ? 'rgba(255,255,255,0.55)' : 'var(--text-muted)' }}>
            พอยต์
          </p>
          <div className="flex items-baseline gap-0.5">
            <span
              ref={countUpRef}
              className="font-black text-[15px] num-display"
              style={{ color: points > 0 ? 'white' : 'var(--text-primary)' }}
            >
              {points.toLocaleString()}
            </span>
            <span className="text-[9px] font-bold" style={{ color: points > 0 ? 'rgba(255,255,255,0.5)' : 'var(--text-muted)' }}>pts</span>
          </div>
          {points > 0 && (
            <div className="flex items-center gap-0.5 mt-0.5">
              <ChevronRight className="w-2.5 h-2.5" style={{ color: 'rgba(255,255,255,0.4)' }} />
              <p className="text-[8px] font-bold" style={{ color: 'rgba(255,255,255,0.4)' }}>แลกส่วนลด</p>
            </div>
          )}
        </div>
      </motion.button>

    </motion.div>
  )
}
